  breath_init();
  breath_set_velocity(100);
  breath_step();
  breath_step();
  breath_step();
  ASSERT_EQ(breath_brightness(), 255);
  ASSERT_TRUE(breath_is_rising());
  breath_step();
  ASSERT_EQ(breath_brightness(), 255);
  ASSERT_FALSE(breath_is_rising());
